function isPrime(n){
  n=Math.floor(n);
  if(n<2) return false;
  if(n<4) return true;
  if(n%2===0) return false;
  for(var i=3;i*i<=n;i+=2){ if(n%i===0) return false; }
  return true;
}
function gcd(a,b){ a=Math.abs(Math.floor(a)); b=Math.abs(Math.floor(b)); while(b){ var t=b; b=a%b; a=t; } return a; }
function lcm(a,b){ if(!a||!b) return 0; return Math.abs(a*b)/gcd(a,b); }
function factorize(n){
  n=Math.floor(n); var res={};
  if(n<2) return res;
  var m=Math.abs(n); var sign = n<0 ? -1 : 1;
  for(var p=2;p*p<=m;p++){ while(m%p===0){ res[p]=(res[p]||0)+1; m=Math.floor(m/p); } }
  if(m>1) res[m]=(res[m]||0)+1;
  if(sign<0 && res[2]) res[2]=res[2]; // 符号另算
  return res;
}
function primesUpTo(n){
  n=Math.floor(n); var r=[];
  if(n<2) return r;
  var s=new Array(n+1).fill(true); s[0]=s[1]=false;
  for(var i=2;i*i<=n;i++){ if(s[i]){ for(var j=i*i;j<=n;j+=i) s[j]=false; } }
  for(var k=2;k<=n;k++) if(s[k]) r.push(k);
  return r;
}
function nextPrime(n){ n=Math.floor(n); var c=n+1; while(!isPrime(c)) c++; return c; }
function prevPrime(n){ n=Math.floor(n); if(n<=2) return null; var c=n-1; while(c>1 && !isPrime(c)) c--; return c>1?c:null; }
function factorString(n){
  var f=factorize(n); var parts=[];
  for(var p in f){ if(!f.hasOwnProperty(p)) continue; parts.push(f[p]===1?String(p):p+"^"+f[p]); }
  return parts.length?parts.join(" × "):"1";
}
var EXPORTS={ isPrime:isPrime, gcd:gcd, lcm:lcm, factorize:factorize, primesUpTo:primesUpTo, nextPrime:nextPrime, prevPrime:prevPrime, factorString:factorString };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PrimeForgePure = EXPORTS; }
